import { useLayoutEffect, useMemo, useState } from "react"
import { fn } from "storybook/test"
import type { Meta, StoryObj } from "@storybook/react-vite"
import type { Vulnerability } from "@exposurenexus/types/model/vulnerability"
import { VulnerabilityTable } from "@/components/vulnerability-table"
import { STORY_VULNERABILITIES } from "@/components/storybook-fixtures.ts"
import {
  RouterStoryProvider,
  createArrayResponse,
  createStoryQueryClient
} from "@/components/storybook-utils.tsx"

type VulnerabilityTableStoryArgs = {
  vulnerabilities: Array<Vulnerability>
  scenario: "default" | "empty" | "loading"
  selectedVulnerabilityId?: string
  onSelectVulnerability?: (vulnerability: Vulnerability) => void
  onCreateVulnerability?: () => void
  onDeleteVulnerabilities?: (
    vulnerabilities: Array<Vulnerability>
  ) => Promise<void>
}

function VulnerabilityTableStoryShell({
  vulnerabilities,
  scenario,
  selectedVulnerabilityId,
  onSelectVulnerability,
  onCreateVulnerability,
  onDeleteVulnerabilities
}: VulnerabilityTableStoryArgs) {
  const effectiveVulnerabilities = scenario === "empty" ? [] : vulnerabilities
  const queryClient = useMemo(() => {
    const client = createStoryQueryClient()

    if (scenario !== "loading") {
      client.setQueryData(["vulnerabilities"], effectiveVulnerabilities)
    }

    return client
  }, [effectiveVulnerabilities, scenario])
  const [ready, setReady] = useState(scenario !== "loading")

  useLayoutEffect(() => {
    const originalFetch = globalThis.fetch

    globalThis.fetch = async (input, init) => {
      const requestUrl = input instanceof Request ? input.url : String(input)

      if (requestUrl.endsWith("/api/vulnerabilities")) {
        if (scenario === "loading") {
          return await new Promise<Response>(() => {})
        }

        return createArrayResponse(effectiveVulnerabilities)
      }

      return originalFetch(input, init)
    }

    setReady(true)

    return () => {
      globalThis.fetch = originalFetch
    }
  }, [effectiveVulnerabilities, scenario])

  if (!ready) {
    return null
  }

  return (
    <RouterStoryProvider
      queryClient={queryClient}
      initialPath="/vulnerabilities"
      withNuqs
    >
      <div className="w-full max-w-6xl">
        <VulnerabilityTable
          selectedVulnerabilityId={selectedVulnerabilityId}
          onSelectVulnerability={onSelectVulnerability}
          onCreateVulnerability={onCreateVulnerability}
          onDeleteVulnerabilities={onDeleteVulnerabilities}
        />
      </div>
    </RouterStoryProvider>
  )
}

