import { QueryClient, QueryClientProvider } from "@tanstack/react-query"
import { useLayoutEffect, useMemo, useRef, useState } from "react"
import { VulnerabilitySeverity } from "@exposurenexus/types/model/vulnerability"
import type {
  Vulnerability,
  VulnerabilitySourceMapping
} from "@exposurenexus/types/model/vulnerability"
import type { Meta, StoryObj } from "@storybook/react-vite"
import type { UserProfile } from "@exposurenexus/types/model/user"
import { VulnerabilityDetailContent } from "@/components/vulnerability-detail-content.tsx"
import { ConfirmDialog } from "@/components/confirm-dialog.tsx"

type VulnerabilityDetailStoryArgs = {
  vulnerability: Vulnerability
  vulnerabilities: Array<Vulnerability>
  mappings: Array<VulnerabilitySourceMapping>
  users: Array<UserProfile>
  scenario: "success" | "empty-mappings" | "loading"
}

const USERS: Array<UserProfile> = [
  {
    id: "1f9c36d2-1355-49d1-8464-b01ce955d88f",
    username: "alice",
    displayName: "Alice Example",
    email: "alice@example.com",
    enabled: true,
    roleIds: []
  },
  {
    id: "4e33f42e-764b-4812-88fb-11a183d43434",
    username: "bob",
    displayName: "Bob Example",
    email: "bob@example.com",
    enabled: true,
    roleIds: []
  }
]

const VULNERABILITY: Vulnerability = {
  id: "9d7acdd0-fad1-46c9-8218-1793f421f0fe",
  title: "Exposed Admin Endpoint",
  severity: VulnerabilitySeverity.High,
  description:
    "## Impact\n\nAdministrative interfaces are **reachable** from the public internet.\n\n## Remediation\n\n- Restrict access to trusted networks\n- Require strong authentication\n- Monitor repeated access attempts",
  cwe: 284,
  cve: "CVE-2026-0001",
  createdBy: USERS[0].id,
  updatedBy: USERS[1].id,
  createdAt: new Date("2026-01-01T00:00:00.000Z"),
  updatedAt: new Date("2026-01-02T00:00:00.000Z")
}

const MAPPINGS: Array<VulnerabilitySourceMapping> = [
  {
    id: "3dcd2647-d0e4-4281-a9cb-5b4eb5955c47",
    vulnerabilityId: VULNERABILITY.id,
    source: "nuclei",
    matchQuery: '{"templateID":"admin-panel"}'
  }
]

const TARGET_VULNERABILITY: Vulnerability = {
  id: "4fb566c6-e642-48d8-b70d-418efb074f8d",
  title: "Account Takeover",
  severity: VulnerabilitySeverity.Critical,
  description:
    "## Impact\n\nA finding can be reclassified into this vulnerability from the mapping manager.",
  cwe: 287,
  cve: null,
  createdBy: USERS[0].id,
  updatedBy: USERS[1].id,
  createdAt: new Date("2026-01-01T00:00:00.000Z"),
  updatedAt: new Date("2026-01-02T00:00:00.000Z")
}

function VulnerabilityDetailContentStoryShell({
  vulnerability,
  vulnerabilities,
  mappings,
  users,
  scenario
}: VulnerabilityDetailStoryArgs) {
  const effectiveMappings = useMemo(
    () => (scenario === "empty-mappings" ? [] : mappings),
    [mappings, scenario]
  )
  const mappingsRef =
    useRef<Array<VulnerabilitySourceMapping>>(effectiveMappings)
  const queryClient = useMemo(() => {
    const client = new QueryClient({
      defaultOptions: {
        queries: {
          retry: false,
          staleTime: Number.POSITIVE_INFINITY
        }
      }
    })

    if (scenario !== "loading") {
      client.setQueryData(["vulnerabilities"], vulnerabilities)
      client.setQueryData(["vulnerabilities", vulnerability.id], vulnerability)
      client.setQueryData(
        ["vulnerabilities", vulnerability.id, "mappings"],
        effectiveMappings
      )
      client.setQueryData(
        ["vulnerability-mappings", { source: null }],
        [...effectiveMappings]
      )
      client.setQueryData(
        ["vulnerability-mappings", { source: "nuclei" }],
        [...effectiveMappings]
      )
      client.setQueryData(["users"], users)
    }

    return client
  }, [effectiveMappings, scenario, users, vulnerabilities, vulnerability])
  const [ready, setReady] = useState(scenario !== "loading")

  useLayoutEffect(() => {
    const originalFetch = globalThis.fetch
    mappingsRef.current = effectiveMappings

    globalThis.fetch = async (input, init) => {
      const requestUrl = input instanceof Request ? input.url : String(input)
      const method = (init?.method ?? "GET").toUpperCase()
      const mappingPath = `/api/vulnerabilities/${vulnerability.id}/mappings`

      if (requestUrl.endsWith("/api/vulnerabilities")) {
        if (scenario === "loading") {
          return await new Promise<Response>(() => {})
        }

        return createArrayResponse(vulnerabilities)
      }

      const requestedVulnerability = vulnerabilities.find((candidate) =>
        requestUrl.endsWith(`/api/vulnerabilities/${candidate.id}`)
      )

      if (requestedVulnerability) {
        if (scenario === "loading") {
          return await new Promise<Response>(() => {})
        }

        return createObjectResponse(requestedVulnerability)
      }

      if (requestUrl.endsWith(mappingPath)) {
        if (scenario === "loading") {
          return await new Promise<Response>(() => {})
        }

        if (method === "POST" || method === "PUT") {
          const body = JSON.parse(String(init?.body ?? "{}")) as Pick<
            VulnerabilitySourceMapping,
            "source" | "matchQuery"
          > &
            Partial<Pick<VulnerabilitySourceMapping, "vulnerabilityId">>
          const created: VulnerabilitySourceMapping = {
            id:
              method === "PUT"
                ? requestUrl.slice(requestUrl.lastIndexOf("/") + 1)
                : crypto.randomUUID(),
            vulnerabilityId: body.vulnerabilityId ?? vulnerability.id,
            source: body.source,
            matchQuery: JSON.stringify(JSON.parse(body.matchQuery))
          }

          mappingsRef.current =
            method === "PUT"
              ? mappingsRef.current.map((mapping) =>
                  mapping.id === created.id ? created : mapping
                )
              : [...mappingsRef.current, created]
          queryClient.setQueryData(
            ["vulnerabilities", vulnerability.id, "mappings"],
            mappingsRef.current
          )

          return createObjectResponse(created)
        }

        if (method === "DELETE") {
          const mappingId = requestUrl.slice(requestUrl.lastIndexOf("/") + 1)
          const deleted = mappingsRef.current.find(
            (mapping) => mapping.id === mappingId
          )
          mappingsRef.current = mappingsRef.current.filter(
            (mapping) => mapping.id !== mappingId
          )
          queryClient.setQueryData(
            ["vulnerabilities", vulnerability.id, "mappings"],
            mappingsRef.current
          )

          return createObjectResponse(deleted ?? null)
        }

        return createArrayResponse(mappingsRef.current)
      }

      if (requestUrl.endsWith("/api/findings/reclassify")) {
        return createObjectResponse({
          updatedCount: 3
        })
      }

      if (requestUrl.endsWith("/api/users")) {
        return createArrayResponse(users)
      }

      return originalFetch(input, init)
    }

    setReady(true)

    return () => {
      globalThis.fetch = originalFetch
    }
  }, [
    effectiveMappings,
    queryClient,
    scenario,
    users,
    vulnerabilities,
    vulnerability
  ])

  if (!ready) {
    return null
  }

  return (
    <QueryClientProvider client={queryClient}>
      <ConfirmDialog.Root />
      <div className="w-full max-w-7xl">
        <VulnerabilityDetailContent vulnerabilityId={vulnerability.id} />
      </div>
    </QueryClientProvider>
  )
}

function createObjectResponse(data: unknown): Response {
  return new Response(JSON.stringify({ data }), {
    headers: {
      "Content-Type": "application/json"
    }
  })
}

function createArrayResponse(data: Array<unknown>): Response {
  return new Response(JSON.stringify({ data: { items: data } }), {
    headers: {
      "Content-Type": "application/json"
    }
  })
}

const meta = {
  title: "Resources/Vulnerabilities/Detail",
