  },
  args: {
    vulnerability: VULNERABILITY,
    vulnerabilities: [VULNERABILITY, TARGET_VULNERABILITY],
    mappings: MAPPINGS,
    users: USERS,
    scenario: "success"
  },
  render: (args) => <VulnerabilityDetailContentStoryShell {...args} />
