        if (scenario === "roles-loading") {
          return await new Promise<Response>(() => {})
        }

        return createArrayResponse(ROLE_FIXTURES)
      }

      return originalFetch(input, init)
    }

    setReady(true)

    return () => {
      globalThis.fetch = originalFetch
    }
  }, [effectiveUser, scenario])

  if (!ready) {
    return null
  }

  return (
