function createQueryResult<TData>({
  data,
  isFetching,
  isPending,
  refetch
}: {
  data: Array<TData> | undefined
  isFetching: boolean
  isPending: boolean
  refetch: () => Promise<unknown>
}): UseQueryResult<Array<TData>, Error> {
  return {
    data,
    error: null,
    failureCount: 0,
    failureReason: null,
    errorUpdateCount: 0,
    isError: false,
    isFetched: !isPending,
    isFetchedAfterMount: !isPending,
    isFetching,
    isInitialLoading: isPending,
    isLoading: isPending,
    isLoadingError: false,
    isPaused: false,
    isPending,
    isPlaceholderData: false,
    isRefetchError: false,
    isRefetching: isFetching,
    isStale: false,
    isSuccess: !isPending,
    status: isPending ? "pending" : "success",
    fetchStatus: isFetching || isPending ? "fetching" : "idle",
    dataUpdatedAt: 0,
    errorUpdatedAt: 0,
    isEnabled: true,
    promise: Promise.resolve(data) as Promise<Array<TData>>,
    refetch
  } as unknown as UseQueryResult<Array<TData>, Error>
}

function DataTableStoryShell({
  rows,
  pending = false,
  initialGrouping = [],
  showToolbarControls = false,
  activeRowId,
  onExport = fn()
}: DataTableStoryArgs) {
  const [currentRows, setCurrentRows] = useState(rows)
  const [isFetching, setIsFetching] = useState(false)

  useEffect(() => {
    setCurrentRows(rows)
  }, [rows])

  const handleRefresh = async () => {
    if (pending) {
      return {
        data: undefined,
        error: null,
        isError: false,
        isPending: true,
        isSuccess: false,
        status: "pending"
      }
    }

    setIsFetching(true)
    await new Promise((resolve) => setTimeout(resolve, 450))
    setIsFetching(false)

    return {
      data: currentRows,
      error: null,
      isError: false,
      isPending: false,
      isSuccess: true,
      status: "success"
    }
  }

  const query = createQueryResult({
    data: pending ? undefined : currentRows,
    isFetching,
    isPending: pending,
    refetch: handleRefresh
  })

  return (
    <div className="w-full space-y-4">
      <DataTable
        columns={columns}
        query={query}
        groupingOptions={groupingOptions}
        initialGrouping={initialGrouping}
        onRowDelete={async (selectedRows) => {
          await Promise.resolve()
          setCurrentRows((existingRows) =>
            existingRows.filter(
              (row) =>
                !selectedRows.some((selectedRow) => selectedRow.id === row.id)
            )
          )
        }}
        onRowClick={fn()}
        onRowDoubleClick={fn()}
        isRowActive={activeRowId ? (row) => row.id === activeRowId : undefined}
        toolbarControls={
          showToolbarControls ? (
            <Button
              variant="default"
              size="sm"
              className="h-9 rounded-xl"
              onClick={onExport}
            >
              <DatabaseBackup />
              Export CSV
            </Button>
          ) : undefined
        }
      />
    </div>
  )
}

